-- Recovered from the linked project's Supabase migration history.

-- Add 80 curated Think Fast prompts while preserving the existing 300-card deck.
begin;

create temporary table decked_think_fast_additions_v2(item_id uuid primary key,family text not null,sort_order integer not null,source_item_id uuid not null,source_index integer not null,body text not null,metadata jsonb not null) on commit drop;


do $$ declare matched integer; begin select count(*) into matched from public.content_items item join decked_think_fast_additions_v2 addition on addition.source_item_id=item.id where item.game_id='think-fast'; if matched<>80 then raise exception 'Think Fast V2 source inventory mismatch: expected 80 source IDs, found %',matched; end if; end $$;




commit;
